 "content": "def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    runs = []
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            start = c
            while c < w and row[c] != bg:
                c += 1
            runs.append((r, start, row[start:c]))
    _, _, motif = max(runs, key=lambda item: len(item[2]))
    motif_colors = set(motif)
    marker_color = next(v for v in counts if v != bg and v not in motif_colors)
    out = [row[:] for row in grid]
    # The marker is the center of the copied horizontal pattern.
    half = len(motif) // 2
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker_color:
                for j, color in enumerate(motif):
                    cc = c + j - half
                    if 0 <= cc < w:
                        out[r][cc] = color
    return out
